import re
for out in ["index.html","business.html","products.html","company.html","contact.html","privacy.html"]:
    f=P/out
    def chunk(m):
        t=m.group(1)
        if t not in PHRASES:return m.group(0)
        return ">"+"".join('<span class="phrase">'+v+"</span>" for v in PHRASES[t].split("|"))+"<"
    f.write_text(re.sub(r">([^<>]+)<",chunk,f.read_text()))
